void PageHandlerAsyncWaiter::GetIsTorConnected(
    bool* out_is_connected) {
  base::RunLoop loop;
  proxy_->GetIsTorConnected(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_is_connected
,
             bool is_connected) {*out_is_connected = std::move(is_connected);
            loop->Quit();
          },
          &loop,
          out_is_connected));
  loop.Run();
}

bool PageHandlerAsyncWaiter::GetIsTorConnected(
    ) {
  bool async_wait_result;
  GetIsTorConnected(&async_wait_result);
  return async_wait_result;
}




